using System;
namespace PKBall.Prototype {
    // UI shows these reference values without converting inherited fields into permanent overrides.
    public static class PrototypeBroadcastDefaults {
        public static PrototypeItemAnimation Animation(PrototypeBroadcastSlot slot,PrototypeItemDefinition definition)=>slot.animationSchemaVersion==0 || slot.animation==null?PrototypeItemAnimationDefaults.Resolve(definition):slot.animation.Clone();
        public static float Value(PrototypeBroadcastSlot s,PrototypeItemDefinition d,string key){var w=d?.weapon;bool weapon=w!=null||s.weaponKind>=0;
            switch(key){case "damage":return w!=null?w.damage:weapon?0:Effect(s,d,PrototypeEffectKind.Damage,s.effectMultiplier);case "cooldown":return w!=null?w.cooldown:weapon?4:d?.activationCooldown??4;case "range":return w?.range??2;case "visualScale":return w?.visualScale??1;case "visualSize":return w?.visualSize??.8f;case "effectScale":return w?.effectScale??1;case "projectileSpeed":return w?.projectileSpeed??8;case "projectileSize":return w?.projectileSize??.18f;case "hitDelay":return w?.hitDelay??.12f;case "animationDuration":return w?.animationDuration??.3f;case "knockback":return w?.knockbackImpulse??.5f;case "visualCount":return w?.visualCount??1;case "healthBonus":return d?.healthBonus??0;case "speedBonus":return d?.speedBonus??0;case "poison":return Effect(s,d,PrototypeEffectKind.Poison,s.effectMultiplier);case "burn":return Effect(s,d,PrototypeEffectKind.Burn,s.effectMultiplier);case "shield":return Effect(s,d,PrototypeEffectKind.Shield,s.effectMultiplier);case "heal":return Effect(s,d,PrototypeEffectKind.Heal,s.effectMultiplier);case "regeneration":return Effect(s,d,PrototypeEffectKind.Regeneration,s.effectMultiplier);case "effectMultiplier":case "cooldownMultiplier":case "releaseVolume":case "hitVolume":return 1;case "growth":return 0;default:throw new ArgumentException("Unknown numeric field: "+key);}}
        static float Effect(PrototypeBroadcastSlot s,PrototypeItemDefinition d,PrototypeEffectKind kind,float multiplier){float amount=0;var effects=s.overridesEffects?s.effectsOverride:d?.effects;if(effects!=null)foreach(var e in effects)if(e.kind==kind)amount+=e.amount;return amount*multiplier;}
    }
}
